-- Seed awal Ujian Online. Jalankan setelah migration 20260919100000_add_exam_and_learning_history.sql.
on conflict(name) do update set label=excluded.label,description=excluded.description,sort_order=excluded.sort_order;
select id,'Ujian '||name,'Ujian online kategori '||name||' Kryzna Learn.',30,70,true from public.exam_categories
on conflict(category_id,title) do update set is_published=true,updated_at=now();
